begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
('12000000-0000-4000-8000-000000000001','recovery@example.test','{"first_name":"Recovery","last_name":"Staff"}'),
('12000000-0000-4000-8000-000000000002','recovery-other@example.test','{"first_name":"Other","last_name":"Staff"}');
update public.profiles set is_active = true where id in ('12000000-0000-4000-8000-000000000001','12000000-0000-4000-8000-000000000002');
insert into public.user_roles (user_id, role) values ('12000000-0000-4000-8000-000000000001','STAFF'),('12000000-0000-4000-8000-000000000002','STAFF');

create temp table fixture_ids(kind text primary key,id uuid);grant all on fixture_ids to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"12000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fixture_ids select 'client',id from public.save_client(auth.uid(),null,null,'Recovery','Family','+13035550120','recovery-family@example.test','EMAIL',null,null);
insert into fixture_ids select 'conversation',id from public.ensure_active_conversation((select id from fixture_ids where kind='client'));
select throws_ok($$select public.enqueue_communication(auth.uid(),'12000000-0000-4000-8000-000000000010',(select id from fixture_ids where kind='conversation'),'EMAIL','recovery-family@example.test','Visit','Exact saved draft')$$,'42501',null,'Old unprepared client cannot enqueue');
select lives_ok($$select public.prepare_message_request(auth.uid(),'12000000-0000-4000-8000-000000000010','new-message',(select id from fixture_ids where kind='conversation'),'EMAIL','recovery-family@example.test','Visit','Exact saved draft')$$,'Preparation stores a durable snapshot');
select is((select count(*) from public.communication_outbox),0::bigint,'Preparation never creates outbound work');
select is((public.recover_message_request(auth.uid(),'new-message','12000000-0000-4000-8000-000000000010')->'payload'->>'body'),'Exact saved draft','Reload retrieves exact prepared body');
select lives_ok($$select public.prepare_message_request(auth.uid(),'12000000-0000-4000-8000-000000000010','new-message',(select id from fixture_ids where kind='conversation'),'EMAIL','recovery-family@example.test','Visit','Exact saved draft')$$,'Lost prepare response can retry same UUID');
select throws_ok($$select public.prepare_message_request(auth.uid(),'12000000-0000-4000-8000-000000000010','new-message',(select id from fixture_ids where kind='conversation'),'EMAIL','recovery-family@example.test','Visit','Different draft')$$,'23505',null,'Prepared payload cannot be replaced');
select throws_ok($$select public.prepare_message_request(auth.uid(),'12000000-0000-4000-8000-000000000011','new-message',(select id from fixture_ids where kind='conversation'),'EMAIL','recovery-family@example.test','Visit','Other tab')$$,'23505',null,'Second unresolved request for actor scope rejected');
select is(public.recover_message_request(auth.uid(),'other-scope','12000000-0000-4000-8000-000000000010'),null::jsonb,'Scope mismatch reveals no payload');
select throws_ok($$select public.recover_message_request('12000000-0000-4000-8000-000000000002','new-message','12000000-0000-4000-8000-000000000010')$$,'42501',null,'Recovery rejects forged actor argument');
select set_config('request.jwt.claims','{"sub":"12000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(public.recover_message_request(auth.uid(),'new-message','12000000-0000-4000-8000-000000000010'),null::jsonb,'Other signed-in account cannot read prepared content');
select is((select count(*) from public.communication_prepared_requests),0::bigint,'Direct reads remain owner scoped');
select set_config('request.jwt.claims','{"sub":"12000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.enqueue_communication(auth.uid(),'12000000-0000-4000-8000-000000000010',(select id from fixture_ids where kind='conversation'),'EMAIL','recovery-family@example.test','Visit','Changed after prepare')$$,'23505',null,'Queue cannot bypass immutable prepared content');
select lives_ok($$select public.enqueue_communication(auth.uid(),'12000000-0000-4000-8000-000000000010',(select id from fixture_ids where kind='conversation'),'EMAIL','recovery-family@example.test','Visit','Exact saved draft')$$,'Exact prepared request enters outbox');
select is((public.recover_message_request(auth.uid(),'new-message','12000000-0000-4000-8000-000000000010')->'receipt'->>'state'),'pending','Recovery exposes queue receipt without claiming delivery');
select is((public.resolve_message_request(auth.uid(),'12000000-0000-4000-8000-000000000010','new-message',false)->>'status'),'acknowledged','Acknowledgement releases composer scope');
select is((select count(*) from public.communication_prepared_requests),1::bigint,'Acknowledgement retains prepared history');
select lives_ok($$select public.enqueue_communication(auth.uid(),'12000000-0000-4000-8000-000000000010',(select id from fixture_ids where kind='conversation'),'EMAIL','recovery-family@example.test','Visit','Exact saved draft')$$,'Retry after acknowledgement still returns original outbox');
select is((select count(*) from public.communication_outbox),1::bigint,'No duplicate queue item after acknowledged retry');
select lives_ok($$select public.resolve_message_request(auth.uid(),'12000000-0000-4000-8000-000000000020','new-message',true)$$,'Unknown preparation can be explicitly tombstoned');
select throws_ok($$select public.prepare_message_request(auth.uid(),'12000000-0000-4000-8000-000000000020','new-message',(select id from fixture_ids where kind='conversation'),'EMAIL','recovery-family@example.test','Visit','Late preparation')$$,'23505',null,'Late prepare cannot revive abandoned unknown request');
select throws_ok($$select public.enqueue_communication(auth.uid(),'12000000-0000-4000-8000-000000000020',(select id from fixture_ids where kind='conversation'),'EMAIL','recovery-family@example.test','Visit','Late preparation')$$,'42501',null,'Abandoned request cannot enqueue');
select public.prepare_message_request(auth.uid(),'12000000-0000-4000-8000-000000000030','new-message',(select id from fixture_ids where kind='conversation'),'SMS','+13035550120','','Saved before consent');
select throws_ok($$select public.enqueue_communication(auth.uid(),'12000000-0000-4000-8000-000000000030',(select id from fixture_ids where kind='conversation'),'SMS','+13035550120','','Saved before consent')$$,'42501',null,'Queue still requires current SMS consent after preparation');
select throws_ok($$select public.enqueue_prepared_communication_internal(auth.uid(),'12000000-0000-4000-8000-000000000030',(select id from fixture_ids where kind='conversation'),'SMS','+13035550120','','Saved before consent')$$,'42501',null,'Private queue implementation cannot bypass preparation');
select throws_ok($$update public.communication_prepared_requests set payload='{}'$$,'42501',null,'Browser cannot rewrite preparation');
select public.prepare_message_request(auth.uid(),'12000000-0000-4000-8000-000000000040','recipient-change',(select id from fixture_ids where kind='conversation'),'EMAIL','recovery-family@example.test','Visit','Prepared before contact edit');
reset role;
update public.clients set primary_email='new-contact@example.test' where id=(select id from fixture_ids where kind='client');
set local role authenticated;
select throws_ok($$select public.enqueue_communication(auth.uid(),'12000000-0000-4000-8000-000000000040',(select id from fixture_ids where kind='conversation'),'EMAIL','recovery-family@example.test','Visit','Prepared before contact edit')$$,'42501',null,'Queue revalidates current recipient after preparation');
reset role;
select throws_ok($$delete from public.communication_prepared_requests$$,'23514',null,'Prepared history cannot be deleted');
select * from finish();
rollback;
